<!DOCTYPE html><html><head><meta charset="utf-8"><style>body{font-family:sans-serif;font-size:12px;color:#222}table{width:100%;border-collapse:collapse}th,td{border:1px solid #bbb;padding:6px;vertical-align:top}h1{margin:0 0 8px} .meta{margin-bottom:12px}</style></head><body><h1><?= esc($title ?? 'Jadwal Seni') ?></h1><div class="meta">Tanggal: <?= esc($jadwal->tanggal ?? '-') ?> | Arena: <?= esc($jadwal->nama_gelanggang ?? '-') ?> | Jam: <?= esc($jadwal->jam_mulai ?? '-') ?> - <?= esc($jadwal->jam_selesai ?? '-') ?></div><table><thead><tr><th>No. Partai</th><th>Jenis</th><th>Babak</th><th>Kontingen / Kelompok</th><?php if (! empty($withScore)) : ?><th>Nilai</th><?php endif; ?></tr></thead><tbody><?php foreach (($details ?? []) as $row) : ?><tr><td><?= esc((string) ($row->nomor_partai ?? '-')) ?></td><td><?= esc(! empty($row->id_battle_seni) ? 'Battle' : 'Pool') ?></td><td><?= esc($row->babak_battle ?? $row->babak_pool ?? '-') ?></td><td><?= esc(($row->nama_kontingen ?? $row->nama_kontingen_merah ?? '-') . (! empty($row->nama_kontingen_biru) ? ' vs ' . $row->nama_kontingen_biru : '')) ?></td><?php if (! empty($withScore)) : ?><td><?= esc((string) ($row->nilai_akhir ?? (($row->nilai_akhir_merah ?? '-') . ' - ' . ($row->nilai_akhir_biru ?? '-')))) ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></body></html>